// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1 ether);

        uint256 orig = actor.balance;

        // actor funds the contract through the payable fallback
        vm.deal(actor, amount);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertEq(address(c).balance, amount);
        assertEq(c.depositsCount(), 1);

        // owner triggers the payout path
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        assertTrue(ok);

        // RULE: after withdrawAll, the owner (caller) has been paid the full
        // balance, i.e. the actor is exactly reimbursed to its pre-deposit wealth.
        assertTrue(actor.balance == orig);
    }
}

