// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != c.owner());
        vm.assume(caller != address(0));
        amount = bound(amount, 1, 100 ether);

        // fund the contract so the transfer can succeed
        vm.deal(address(c), amount);

        uint256 ownerBefore = c.owner().balance;
        uint256 callerBefore = caller.balance;

        vm.prank(caller);
        c.withdraw(amount);

        // Rule: a successful withdraw by a non-owner pays msg.sender, never the owner.
        assertTrue(
            caller.balance == callerBefore + amount && c.owner().balance == ownerBefore,
            "withdraw must pay the caller, not the owner"
        );
    }
}

